### Вывод метаданных файла



Мы посмотрели, как получить и вывести на консоль текст файла. В принципе все довольно просто. Но при переборе файлов через свойства объекта **File** нам доступны различные метаданные файла - имя, размер, тип, дата изменения. Что, если мы хотим, к примеру, при выводе текста файла также выводить его имя? Наивный подход выглядел бы следующим образом:



```javascript

for (file of files) {
    console.log("File Name:", file.name);   // выводим имя файла
    const reader = new FileReader();
    reader.onload = () => {  
        console.log("File Name:", file.name);   // можно попробовать вывести здесь
        console.log(reader.result);
        console.log("==============================");
    };      
    reader.readAsText(file);       
}
```



Проблема в том, что обработчик `reader.onload` имеет асинхронную природу - считывание предыдущего файла может завершиться, когда начнется (или даже уже закончено) считывание следующего файла. Соответственно такой подход может привести к коллизиям. Одно из возможных решений состоит в том, что захватить нужные нам данные извне через замыкание:



```javascript

function printFiles(e) {  
    const files = e.target.files;
    for (file of files) {
        
        const reader = new FileReader();
        reader.onload = (function(fileData) {
            return function(e){
                console.log("File Name:", fileData.name);
                console.log(e.target.result); // то же самое, что и reader.result
                console.log("==============================");
            };
        })(file);
        reader.readAsText(file);       
    }
}
```



В данном случае обработчику onload присваивается результат самовыполняющейся функции, которая образует замыкание. Через ее параметр fileData в функцию передается текущий объект File.



### Считывание изображений



Аналогичным образом можно считывать и другие типы файлов. Например, считаем и выведем на веб-страницу изображения:



```xml

<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8" />
    <title>enoobis.ru</title>
    <style>
    div.item {width: 250px; margin:0 10px;}
    .image {width: 250px;}
    </style>
</head>
<body>
<input type="file" id="files" accept="image/*" multiple />
<div id="fileList"></div>
<script>
function printFiles(e) {  
    const files = e.target.files;
    for (file of files) {
        
        const reader = new FileReader();  
        reader.onload = (function(fileData) {
            return function(){
                // создаем элемент div
                const fileItem = document.createElement("div");
                fileItem.className = "fileItem";

                // создаем заголовок для добавляемого файла 
                const fileHeader = document.createElement("h3");
                fileHeader.textContent = fileData.name;
                fileItem.appendChild(fileHeader);

                // создаем элемент img для отображения файла
                const img = document.createElement("img");   
                img.src = reader.result;
                img.className = "image";       
                fileItem.appendChild(img); 
                document.getElementById("fileList").appendChild(fileItem);  
            };
        })(file);
        reader.readAsDataURL(file); 
    }
}
document.getElementById("files").addEventListener("change", printFiles);
</script>
</body>
</html>
```



Теперь для элемента ввода задан фильтр `accept="image/*"`, а все загружаемые изображения отображаются в элементе ` `. Для этого в обработчике onload создаем элемент div, в него добавляем заголовок h3 с именем файла и элемент img с содержимым файла. Содержимое файла считывается с помощью метода `reader.readAsDataURL()`. Пример работы:



![считывание изображений с помощью filereader в javascript](/uploads/course-lectures/62e704e5334d2aab31930d2393ed4d5d59abc578.png)



### Сочетание различных типов



Также можно сочетать открытие файлов различных типов:



```xml

<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8" />
    <title>enoobis.ru</title>
    <style>
    div.item {width: 250px; margin:0 10px;}
    .text{min-height: 80px; width: 250px; border:1px solid #ccc;padding:10px;}
    .image {width: 250px;}
    </style>
</head>
<body>
<input type="file" id="files" multiple />
<div id="fileList"></div>
<script>
const fileList = document.getElementById("fileList");
// создаем элемент, который представляет отдельный файл на странице
function createFileItem(file){
    const fileItem = document.createElement("div");
    fileItem.className = "fileItem";

    // создаем заголовок для добавляемого файла 
    const fileHeader = document.createElement("h3");
    fileHeader.textContent = file.name;
    fileItem.appendChild(fileHeader);
    return fileItem;
}
function readTextFile(file){
    return function(e){
        const fileItem = createFileItem(file);
        // создаем элемент div для вывода текста файла
        const div = document.createElement("div");   
        // переносы строки заменяем на соответствующий текст
        div.textContent = e.target.result.replace("\n", "\n");
        div.className = "text";       
        fileItem.appendChild(div); 
        fileList.appendChild(fileItem);  
    };
}
function readImageFile(file){
    return function(e){
        const fileItem = createFileItem(file);
        // создаем элемент img для отображения файла
        const img = document.createElement("img");   
        img.src = e.target.result;
        img.className = "image";       
        fileItem.appendChild(img); 
        fileList.appendChild(fileItem);  
    };
}
function printFiles(e) {  
    const files = e.target.files;
    for (file of files) {
        // считываем файл
        const reader = new FileReader(); 
        if(file.type.match("text.*")) {      
            reader.onload = readTextFile(file);
            reader.readAsText(file);    
        } 
        else if(file.type.match("image.*")) {      
            reader.onload = readImageFile(file);      
            reader.readAsDataURL(file);    
        }
    }
}
document.getElementById("files").addEventListener("change", printFiles);
</script>
</body>
</html>
```



Здесь в зависимости от того, какой тип представляет файл, создаем определенный элемент (` ` для вывода текстовых файлов и ` ` для вывода изображений). К примеру, выберем файлы разных типов:



![чтение текстовых файлов и изображений с помощью filereader в javascript](/uploads/course-lectures/6e58af5a9a3d8f9e0c1e14a988a412cb825410a0.png)

При загрузке больших файлов через File API может быть полезно информировать пользователей о ходе операции чтения. Для этой цели тип **FileReader** позволяет обрабатывать событие **progress**. В обработчик этого события передается объект, который имеет тип **ProgressEvent** и который предоставляет следующие свойства:





- lengthComputable : булевое свойство, которое указывает, можно ли вычислить прогресс (количество прочитанных байтов) или нет.

- loaded : 64-битное целое число без знака, которое указывает на объем уже загруженных данных

- total : 64-битное целое число без знака, которое хранит общее количество загружаемых данных



Например, возьмем следующую страницу:



```xml

<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8" />
    <title>enoobis.ru</title>
    <style>
    #progress {width:0; height:100%; background-color:#ccc;}
    #progress-bar {width:100px; height:20px; border:1px solid #888;}
    </style>
</head>
<body>
<input type="file" id="files" multiple /><br><br>
<div id="progress-bar">
    <div id="progress"></div>
</div>
<script>
const progressbar = document.getElementById("progress-bar");
const progress = document.getElementById("progress");
// отслеживаем прогресс загрузки
function updateProgress(e) {  
    if (e.lengthComputable) {    
        const percentLoaded = Math.round((e.loaded / e.total) * 100);    
        if (percentLoaded < 100) {      
            progress.style.width = percentLoaded + "%";      
            progress.textContent = percentLoaded + "%";
        } 
    }
}
// обрабатываем выбор файлов
function handleFileSelected(event) { 
    progress.style.width = "0%";  
    progress.textContent = "0%";  

    const reader = new FileReader();
    reader.onprogress = updateProgress;  
    reader.onerror = (e) => console.error(e.target.error);  
    reader.onload = () => {    
        progress.style.width = "100%";    
        progress.textContent = "100%";
    };
    if(event.target.files.length>0) reader.readAsBinaryString(event.target.files[0]);
}
document.getElementById("files").addEventListener("change", handleFileSelected);
</script>
</body>
</html>
```



На странице определен элемент ` ` для выбора файла. Для индикации загрузки файла на странице определен элемент ` ` с вложенным элементом ` `.



В качестве обработчика события **change** для этого элемента ` ` используется функция `handleFileSelected`. В ней устанавливаем начальные значения для индикатора загрузки:



```javascript

progress.style.width = "0%";  
progress.textContent = "0%";
```



Затем создаем объект FileReader и для его события **progress** в качестве обработчика применяем функцию updateProgress. В ней рассчитываем текущее состояние загрузки и соответствующим образом обновляем ширину и текст элемента progress.



```javascript

function updateProgress(e) {  
    if (e.lengthComputable) {    
        const percentLoaded = Math.round((e.loaded / e.total) * 100);    
        if (percentLoaded < 100) {      
            progress.style.width = percentLoaded + "%";      
            progress.textContent = percentLoaded + "%";
        } 
    }
}
```



Поскольку для элемента progress используется серый фоновый цвет, то увеличение ширины приведет к увеличению закрашенной области, что будет индикатором загрузки. И кроме того, по тексту элемента мы сможем увидеть процент данных загруженного файла.



Когда загрузка завершена, у объекта FileReader срабатывает событие **load**, в котором устанавливаем финальные значения для элемента progress.



```javascript

reader.onload = () => {    
    progress.style.width = "100%";    
    progress.textContent = "100%";
};
```



В конце обработчика выбора файла начинаем его загрузку как набора байтов:



```javascript

if(event.target.files.length>0) reader.readAsBinaryString(event.target.files[0]);
```



Для демонстрации обработки прогресса загрузки здесь никак загруженные данные не используются, но естественно мы можем получить эти данные, как описывалось в прошлой статье, и каким-нибудь образом использовать.



Таким образом, при выборе файла начнется загрузка, а элемент progress отобразит индикацию загрузки.



![индикация загрузки файлов с помощью filereader в javascript](/uploads/course-lectures/bab828de63a41b0b5a03051e5820fe261464b758.png)

Основной поток и запускаемые в нем веб-воркеры могут взаимодействовать посредством сообщений. Для отправки сообщения веб-воркеру у объекта **Worker** вызывается метод **postMessage()**:



```javascript

postMessage(message)
postMessage(message, options)
postMessage(message, transfer)
```



В качестве первого и обязательного параметра `message` передается отправляемое сообщение. В качестве сообщения может выступать произвольное значение, например, строка или объект. При передаче веб-воркер получает **копию** этих данных.



Дополнительный, необязательный параметр `options` представляет конфигурационный объект, который с помощью свойства `transfer` устанавливает дополнительно передаваемые данные. Те же данные передаются в третьей версии функции через параметр `transfer`. При передаче веб-воркеру ****переходит владение этими данными, а основной код больше не может использовать эти данные.




Чтобы получать сообщение на стороне веб-воркера, необходимо зарегистрировать функцию-обработчик для события получения сообщения - события **message**. Например, это можно сделать через свойство **onmessage** веб-воркера.



```javascript

// установка обработчика события через addEventListener
worler.addEventListener("message", (event) => { console.log(event.data);});

// установка обработчика события через свойство onmessage
worker.onmessage = (event) => {console.log(event.data);};
```



В обработчика события передается объект MouseEvent, у которого через свойство **data** можно получить переданные данные.



Аналогично чтобы отправить из веб-воркера сообщение в основной поток, у веб-воркера также вызывается метод **postMessage()**. Внутри основного потока можно получить доступ к сообщению в обработчике события **message**



Для примера определим следующий скрипт **worker.js**:



```javascript

// прослушиваем событие message
self.addEventListener("message", (event) => { 
	// выводим полученные из основного потока данные
	console.log(`[Worker] Message received: ${event.data}`);
	// отправляем в ответ основному потоку некоторое сообщение
	self.postMessage("Hello main thread");
});
```



С помощью слова **self** получаем доступ к объекту веб-воркера и устанавливаем для него обработчик события "message". В этом обработчике мы получаем переданные из основного потока данные и с помощью вызова `self.postMessage` отправляем основному потоку некоторый ответ.



В процессе работы веб-воркера может произойти ошибка, в этом случае мы можем обработать событие **error** объекта Worker.



И определим следующую веб-страницу:



```xml

<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8" />
    <title>enoobis.ru</title>
</head>
<body>
<script>
const worker = new Worker("worker.js");

const message = "Hello web worker";
console.log(`[Main thread] Send message: ${message}`);
// отправляем веб-воркеру сообщение
worker.postMessage(message); 
// получаем от веб-воркера сообщения
worker.addEventListener("message", (e) => console.log(`[Main thread] Response from worker: ${e.data}`));
// если произошла ошибка
worker.addEventListener("error", (e) => console.log("Error occurred"));
</script>
</body>
</html>
```



Здесь аналогичным образом с помощью вызова `worker.postMessage()` посылаем веб-воркеру сообщение и также с помощью обработчика события "message" получаем ответ.



